mapper.select:
SELECT 
FROM async_task USE INDEX (uk_task_id)
WHERE task_id = #{taskId}

SELECT 
FROM async_task
WHERE task_type = #{taskType}
AND status = #{status, typeHandler=com.example.asynctask.handler.TaskStatusTypeHandler}
ORDER BY priority DESC, created_time ASC

mapper.update:
UPDATE async_task SET
    status = #{status, typeHandler=com.example.asynctask.handler.TaskStatusTypeHandler},
    version = version + 1,
    updated_time = NOW()
WHERE task_id = #{taskId}
AND version = #{version}

UPDATE async_task SET
    progress = #{progress},
    version = version + 1,
    updated_time = NOW()
WHERE task_id = #{taskId}
AND version = #{version}

UPDATE async_task SET
    retry_count = retry_count + 1,
    version = version + 1,
    updated_time = NOW()
WHERE task_id = #{taskId}
AND version = #{version}

UPDATE async_task SET
    step_logs = #{stepLogs, typeHandler=com.example.asynctask.handler.JsonTypeHandler},
    version = version + 1,
    updated_time = NOW()
WHERE task_id = #{taskId}
AND version = #{version}

UPDATE async_task SET
    error_message = #{errorMessage},
    version = version + 1,
    updated_time = NOW()
WHERE task_id = #{taskId}
AND version = #{version}

